alter table public.tasks add column if not exists urgency text not null default 'Pendente' check (urgency in ('Urgente','Atenção','Pendente'));
alter table public.meetings add column if not exists urgency text not null default 'Pendente' check (urgency in ('Urgente','Atenção','Pendente'));
alter policy tasks_planner_all on public.tasks using (public.is_admin() or (public.owns_wedding(wedding_id) and (public.has_planner_feature('checklist') or public.has_planner_feature('cronograma')))) with check (public.is_admin() or (public.owns_wedding(wedding_id) and (public.has_planner_feature('checklist') or public.has_planner_feature('cronograma'))));
alter policy meetings_planner_all on public.meetings using (public.is_admin() or (public.owns_wedding(wedding_id) and (public.has_planner_feature('reunioes') or public.has_planner_feature('cronograma')))) with check (public.is_admin() or (public.owns_wedding(wedding_id) and (public.has_planner_feature('reunioes') or public.has_planner_feature('cronograma'))));
